INSERT INTO `task_main_template` VALUES
(0,'Nhiệm vụ đầu tiên','Chi tiết nhiệm vụ'),
(1,'Nhiệm vụ tập luyện','Mộc nhân được đặt nhiều tại %1, ngay trước nhà %2\nHãy đánh ngã 5 mộc nhân, \nsau đó quay về nhà báo cáo với ông %2\nĐể đánh, hãy chạm nhanh 2 lần vào đối tượng\nThưởng 1000 sức mạnh\nThưởng 1000 tiềm năng\nThưởng 200tr vàng'),
(2,'Nhiệm vụ tìm thức ăn','Tìm đến %3, tiêu diệt bọn quái %4 và nhặt về 10 đùi gà\nThưởng 1500 sức mạnh\nThưởng 1500 tiềm năng\nThưởng 300tr vàng\nHọc được kỹ năng bay'),
(3,'Nhiệm vụ sao băng','Đi khám phá xem vật thể lạ vừa rơi xuống hành tinh\nThưởng 2000 sức mạnh\nThưởng 2000 tiềm năng\nThưởng 400tr vàng'),
(4,'Nhiệm vụ thử thách','Khủng long mẹ sống tại Trái Đất\nLợn lòi mẹ sống tại Namếc\nQuỷ đất mẹ sống tại Xayda\nDùng tàu vũ trụ để di chuyển sang hành\nkhác\n-Thưởng 4.000 sức mạnh\n-Thưởng 4.000 tiềm năng'),
(5,'Nhiệm vụ thử thách','Lợn lòi mẹ sống tại Namếc\nKhủng long mẹ sống tại Trái Đất\nQuỷ đất mẹ sống tại Xayda\nDùng tàu vũ trụ để di chuyển sang hành\nkhác\n-Thưởng 4.000 sức mạnh\n-Thưởng 4.000 tiềm năng'),
(6,'Nhiệm vụ thử thách','Quỷ đất mẹ sống tại Xayda\nKhủng long mẹ sống tại Trái Đất\nLợn lòi mẹ sống tại Namếc\nDùng tàu vũ trụ để di chuyển sang hành\nkhác\n-Thưởng 4.000 sức mạnh\n-Thưởng 4.000 tiềm năng'),
(7,'Nhiệm vụ giải cứu','Đến khu vực %13,\nHạ 20 con %9\n- Thưởng 8.000 sức mạnh\n- Thưởng 8.000 tiềm năng'),
(8,'Nhiệm vụ tìm ngọc','Ngọc rồng 7 sao đang bị bọn\n%14 cướp đi.\nĐánh bại chúng để tìm lại.\n- Thưởng 15.000 sức mạnh\n- Thưởng 15.000 tiềm năng'),
(9,'Nhiệm vụ bái sư','Tìm đường tới %11, trò chuyện với %10 và xin làm đệ tử'),
(10,'Nhiệm vụ thử sức','Tiêu diệt %12 thể hiện sức mạnh cho %10 thấy'),
(11,'Nhiệm vụ gia tăng sức mạnh','Ra xã hội làm ăn bươn trải, liều thì ăn nhiều, không liều ăn ít, riêng cờ bạc không phải là thứ để chúng ta liều.\r\nAnh tặng chú 1 câu \"Cờ bạc người không chơi là người thắng, Người chơi không bao giờ thắng\".\r\nĐạt các mốc sức mạnh sau'),
(12,'Nhiệm vụ xin phép','Quay về nhà xin ông %2 cho phép tham gia bang hội'),
(13,'Nhiệm vụ gia nhập bang hội','Gia nhập 1 bang hội cùng những người đồng đội thiện chí\\nCùng làm nhiệm với nhau không quản khó khăn'),
(14,'Nhiệm vụ bang hội đầu tiên','Tiến trình sẽ nhanh gấp đôi nếu cùng phối hợp với 1 người đồng đội lên đường làm nhiệm vụ\r\nGợi ý:\r\nHeo rừng xuất hiện tại rừng Bamboo\r\nHeo da xanh xuất \r\nhiện tại núi hoa vàng\r\nHeo xayda xuất hiện tại rừng cọ\r\nHãy tới trạm tàu vũ trụ để có thể di chuyển qua các map'),
(15,'Nhiệm vụ bang hội thứ 2','Tiến trình sẽ nhanh gấp đôi nếu cùng phối hợp với 1 người đồng đội lên đường làm nhiệm vụ'),
(16,'Tiêu diệt quái vật','Tới các hành tinh tiêu diệt quái vật, giải cứu thường dân'),
(17,'Nhiệm vụ thử thách','Đạt 15 triệu sức mạnh\nTham gia và chiến thắng vòng 2 hoặc chiến thắng 3 lần vòng 1 đại hội võ thuật\nThưởng 3 Tr sức mạnh\nThưởng 3 Tr tiềm năng'),
(18,'Nhiệm vụ cam go','Đạt 25 triệu sức mạnh\nVào doanh trại Độc Nhãn tìm diệt Trung Úy Trắng\nTìm Đại Ma Vương Pôcôlô qua mảnh giấy có chữ \'ma\' ở đại hội võ thuật\nThưởng 4 Tr sức mạnh\nThưởng 4 Tr tiềm năng'),
(19,'Nhiệm vụ giúp đỡ Cui','Tìm đường tới thành phố Vegeta, gặp và nói chuyện với Cui'),
(20,'Nhiệm vụ bất khả thi','Đạt 50 triệu sức mạnh\nTiêu diệt bọn tay sai của Fide tại Xayda\n- Thưởng 50.000.000 sức mạnh\n- Thưởng 50.000.000 tiềm năng'),
(21,'Nhiệm vụ tìm diệt đệ tử','Tiêu diệt bọn đệ tử Kuku, Mập Đầu Đinh,\nRambo của Fide đại ca tại Xayda\nCui có thể biết vị trí của chúng, nếu tìm\nkhông thấy hãy đến gặp Cui tại thành\nphố Vegeta\n- Thưởng 20.000.000 sức mạnh\n- Thưởng 20.000.000 tiềm năng'),
(22,'Nhiệm vụ Tiểu đội sát thủ','Tiêu diệt Tiểu Đội Sát Thủ do Fide đại\nca gọi đến tại Xayda\n- Thưởng 20.000.000 sức mạnh\n- Thưởng 20.000.000 tiềm năng'),
(23,'Nhiệm vụ chạm trán Fide đại ca','Luyện tập đạt 2 tỷ sức mạnh\nLên đường tìm diệt Fide đại ca'),
(24,'Chú bé đến từ tương lai','Đến trái đất, rừng bamboo, rừng dương\nxỉ, nam Kamê tìm người lạ\nĐến đảo rùa đưa thuốc cho Quy Lão\nTheo Ca Lích đến tương lai\nGiúp họ diệt bọn bọ hung con\n- Thưởng 1.000.000 sức mạnh\n- Thưởng 1.000.000 tiềm năng'),
(25,'Chạm chán Robot sát thủ lần 1','Hãy đến thành phố phía nam\nđảo balê hoặc cao nguyên\nCùng 2 đồng bang diệt 900 Xên con cấp 3\nBáo với Bunma tương lai\n- Thưởng 1.000.000 sức mạnh\n- Thưởng 1.000.000 tiềm năng'),
(26,'Chạm trán Robot sát thủ lần 2','Trở về quá khứ, đến sân sau siêu thị\nTiêu diệt bọn Rôbốt sát thủ\nBáo với Bunma tương lai\n- Thưởng 1.000.000 sức mạnh\n- Thưởng 1.000.000 tiềm năng'),
(27,'Chạm trán Robot sát thủ lần 3','Đến thành phố, ngọn núi, thung lũng phía Bắc\nTiêu diệt bọn Rôbốt sát thủ\nCùng 2 đồng bang diệt 800 Xên con cấp 5\nBáo với Bunma tương lai\n- Thưởng 1.000.000 sức mạnh\n- Thưởng 1.000.000 tiềm năng'),
(28,'Chạm trán Xên bọ hung','Đến thị trấn Ginder\nTiêu diệt Xên Bọ Hung cấp 1\nTiêu diệt Xên Bọ Hung cấp 2\nTiêu diệt Xên Bọ Hung hoàn thiện\nCùng 2 đồng bang diệt 700 Xên con cấp 8\nBáo với Bunma tương lai\n- Thưởng 1.000.000 sức mạnh\n- Thưởng 1.000.000 tiềm năng'),
(29,'Cuộc dạo chơi của xên','Cẩn thận !!!\nNhững vị khách không mời mà tới\nthường tỏ ra nguy hiểm'),
(30,'Cuộc đối đầu không cân sức','Vào lúc 12h trưa các ngày, bạn đến gặp NPC Ô sin tại map Đại hội võ thuật.'),
(31,'Chạm trán người ngoài hành tinh','Bảo vệ hành tinh thực vật, hạ những kẻ xâm lược.\nThưởng 10 Tr sức mạnh\nThưởng 10 Tr tiềm năng'),
(32,'Vui lòng chờ nhiệm vụ mới','Vui lòng chờ nhiệm vụ mới');
